"""Write ml/RESULTS.md from the metrics JSON (every number in the report is generated, none typed by hand)."""
import json, pathlib
HERE = pathlib.Path(__file__).resolve().parent
R = HERE / "results"
lg, lb = json.load(open(R / "metrics_logit.json")), json.load(open(R / "metrics_lgbm.json"))
fc = json.load(open(R / "forecast_metrics.json"))
case = json.load(open(R / "redsea_case.json"))
NAMES = {"vantage": "**Vantage** (model + observed drop)", "app": "Previous app scoring", "naive15": "Naive: 7d vs 90d drop > 15%", "naive": "Naive, tuned drop threshold"}
L = []
w = L.append
w("# Backtest results (auto-generated by `ml/write_report.py`)\n")
w(f"Walk-forward, quarterly retraining from {lg['folds_from']} to 2026-10, seed {lg['seed']}. Day-level false-alarm budget {lg['far_target']:.0%}, false alert episodes budget {lg['episode_budget_per_chokepoint_year']}/chokepoint-year. Persistence {lg['persistence']['on_days']} days to raise, {lg['persistence']['off_days']} to clear.\n")
for H, label in (("H14", "14-day horizon (production)"), ("H7", "7-day horizon")):
    r = lg[H]
    w(f"\n## {label}: logistic model, {r['test_rows']:,} chokepoint-days\n")
    w("| System | Precision | Recall | F1 | False-alarm rate | Events warned before traffic fell | Events detected at all | Median lead (days) | False alert episodes / chokepoint-year |")
    w("|---|---|---|---|---|---|---|---|---|")
    for k in ("vantage", "app", "naive15", "naive"):
        a, e = r[k]["all_days"], r[k]["events"]
        w(f"| {NAMES[k]} | {a['precision']:.1%} | {a['recall']:.1%} | {a['f1']:.3f} | {a['false_alarm_rate']:.2%} | {e['warned_early']} / {e['events']} | {e['detected']} / {e['events']} | {e['median_lead_days']:+.1f} | {e['false_alerts_per_chokepoint_year']:.2f} |")
    p = r["probability"]
    w(f"\nModel probability (days when the chokepoint is in normal state; {p['positives']} positive days of {p['n']:,}): ROC-AUC **{p['roc_auc']:.3f}**, PR-AUC **{p['pr_auc']:.3f}** ({p['pr_auc_lift']:.1f}x the {p['base_rate']:.2%} base rate), Brier {p['brier_calibrated']:.5f} vs {p['brier_climatology']:.5f} for always predicting the base rate (skill {p['brier_skill']:+.1%}), uncalibrated Brier {p['brier_uncalibrated']:.4f}.\n")
    e = r["vantage"]["early_warning_stratum"]
    w(f"Early-warning stratum only (chokepoints still at >= 85% of normal traffic, where reactive rules are blind): Vantage TP {e['tp']}, FP {e['fp']}, FN {e['fn']}; previous scoring TP {r['app']['early_warning_stratum']['tp']}, FP {r['app']['early_warning_stratum']['fp']}.\n")
w("\n## Model families (14-day horizon)\n")
w("| Model | ROC-AUC | PR-AUC | Early-warned events | False alert episodes / yr | Day false-alarm rate |")
w("|---|---|---|---|---|---|")
for name, m in (("Logistic regression (14 features) - production", lg), ("LightGBM (26 features)", lb)):
    r = m["H14"]; p = r["probability"]; e = r["vantage"]["events"]
    w(f"| {name} | {p['roc_auc']:.3f} | {p['pr_auc']:.3f} | {e['warned_early']} / {e['events']} | {e['false_alerts_per_chokepoint_year']:.2f} | {r['vantage']['all_days']['false_alarm_rate']:.2%} |")
w("\nProduction model chosen by a rule fixed before looking at the comparison: higher PR-AUC at the 14-day horizon, tie-broken by fewer false alert episodes. It is also exactly interpretable (contribution = coefficient x scaled value).\n")
w("\n## 7-day forecast (quantile LightGBM, walk-forward)\n")
w(f"MAE {fc['mae_model']:.4f} vs {fc['mae_persistence']:.4f} for persistence ({fc['mae_improvement_pct']:.1f}% better); the 80% interval covers {fc['coverage_80']:.1%} (mean width {fc['mean_interval_width']:.2f}). On the {fc['big_drop_n']} chokepoint-days followed by a week below 70% of normal, the forecast is **worse** than persistence (MAE {fc['big_drop_mae_model']:.3f} vs {fc['big_drop_mae_persistence']:.3f}): sudden collapses are not predictable from transit data.\n")
w("\n## Red Sea case study\n")
a = case["alertDates"]
bab = next((e for e in lg["H14"]["vantage"]["events"]["detail"] if e["portname"] == "Bab el-Mandeb Strait"), None)
babapp = next((e for e in lg["H14"]["app"]["events"]["detail"] if e["portname"] == "Bab el-Mandeb Strait"), None)
w(f"Replayed news layer (deterministic headline score, 7-day window): crossed 45 on **{a['newsLayer45']}**, crossed 70 on **{a['newsLayer70']}**. Trained transit model (walk-forward, Bab el-Mandeb): first alert **{bab.get('first_alert', 'none') if bab else 'n/a'}**; previous traffic-only scoring: **{babapp.get('first_alert', 'none') if babapp else 'n/a'}**. Major carriers announced pauses on 15-18 Dec 2023 (public reporting), so the trained transit model alerted about as the carriers reacted, while the news layer was about four weeks earlier. The transit model did not use the headline surge from 20 Nov because no comparable event existed in its training data.\n")
w("| Alert date | Hazard score | Decision | Suez route (days, expected cost) | Cape route (days, expected cost) | Expected saving |")
w("|---|---|---|---|---|---|")
for p in case["pricing"]:
    w(f"| {p['date']} | {p['score']} | {p['decision']} | {p['originalDays']} d, ${p['originalExpectedUsd'] / 1e6:.2f}M | {p['backupDays']} d, ${p['backupExpectedUsd'] / 1e6:.2f}M | ${p['netSavingUsd'] / 1e6:.2f}M |")
s = case["shipment"]
w(f"\nShipment: {s['cargo']}, ${s['cargoValueUsd'] / 1e6:.0f}M critical cargo, Singapore to Rotterdam, {s['speedKnots']} kn, ${s['dailyCostUsd'] / 1000:.0f}k/day. Costs are the app's cost model (expected values under stated assumptions), not realised losses.\n")
w("\n## Events in the test period (14-day horizon)\n")
w("| Chokepoint | Visible start | Sustained-drop onset | Vantage | Previous scoring |")
w("|---|---|---|---|---|")
ev = {k: {(e["portname"], e["visible_start"]): e for e in lg["H14"][k]["events"]["detail"]} for k in ("vantage", "app")}
def cell(e): return f"{e['lead_days']:+d} d" if e["detected"] else "missed"
for k in sorted(ev["vantage"], key=lambda x: x[1]):
    e = ev["vantage"][k]
    w(f"| {k[0]} | {k[1]} | {e['onset']} | {cell(e)} | {cell(ev['app'][k])} |")
w("\n(Lead = days of warning before traffic visibly fell below 85% of normal; negative = alerted late.)\n")
(HERE / "RESULTS.md").write_text("\n".join(L), encoding="utf-8")
print("wrote ml/RESULTS.md")
